CREATE OR REPLACE VIEW vw_pending_fees AS SELECT st.student_id,st.enrollment_no,fs.fee_structure_id,fs.fee_name,fs.amount,fs.due_date FROM student st JOIN fee_structure fs ON fs.program_id=st.program_id LEFT JOIN fee_payment fp ON fp.student_id=st.student_id AND fp.fee_structure_id=fs.fee_structure_id WHERE fp.fee_payment_id IS NULL;
CREATE OR REPLACE VIEW vw_fee_collection AS SELECT fs.fee_name,COUNT(fp.fee_payment_id) payments,SUM(fp.total_amount) collected FROM fee_structure fs LEFT JOIN fee_payment fp ON fp.fee_structure_id=fs.fee_structure_id GROUP BY fs.fee_structure_id,fs.fee_name;
CREATE OR REPLACE VIEW vw_room_occupancy AS SELECT h.hostel_name,r.hostel_room_id,r.room_no,r.capacity,COUNT(ha.hostel_allocation_id) occupied,r.capacity-COUNT(ha.hostel_allocation_id) vacant FROM hostel_room r JOIN hostel h ON h.hostel_id=r.hostel_id LEFT JOIN hostel_allocation ha ON ha.hostel_room_id=r.hostel_room_id AND ha.status='ACTIVE' GROUP BY h.hostel_name,r.hostel_room_id,r.room_no,r.capacity;
